    {"SetAttributes[h, {Flat, Orderless, OneIdentity}]; ReplaceList[h[a, b, c], h[x_Symbol, y___] :> {x, y}]", {{a, b, c}, {b, a, c}, {c, a, b}}},
    (* Flat+Orderless enumeration order *)
    {"SetAttributes[h, {Flat, Orderless, OneIdentity}]; ReplaceList[h[1, a], h[x_Symbol, y___] :> {x, y}]", {{a, 1}}},
    (* Flat+Orderless enumeration order *)
    {"SetAttributes[h, {Flat, Orderless, OneIdentity}]; ReplaceList[h[a, a], h[x_Symbol, y___] :> {x, y}]", {{a, a}, {a, a}}},
    (* Flat+Orderless enumeration order *)
    {"SetAttributes[h, {Flat, Orderless, OneIdentity}]; ReplaceList[h[a, b, a], h[x_Symbol, y___] :> {x, y}]", {{a, a, b}, {a, a, b}, {b, a, a}}},
    (* Flat+Orderless enumeration order *)
    {"SetAttributes[h, {Flat, Orderless, OneIdentity}]; ReplaceList[h[h[a, b], c], h[x_Symbol, y___] :> {x, y}]", {{a, b, c}, {b, a, c}, {c, a, b}}},
    (* Flat+Orderless enumeration order *)
    {"SetAttributes[h, {Flat, Orderless, OneIdentity}]; ReplaceList[h[], h[x_Symbol, y___] :> {x, y}]", {}},
    (* Flat+Orderless enumeration order *)
    {"SetAttributes[h, {Flat, Orderless, OneIdentity}]; ReplaceList[a, h[x_Symbol, y___] :> {x, y}]", {}},
    (* ---- 17. Definitions: specificity, defaults, conditions (2 cases) ---- *)
    (* Flat without OneIdentity in a definition: the reference wraps single operands (x -> q[1]) *)
    {"SetAttributes[q, Flat]; q[x_, y_] := {x, y}; q[1, 2, 3]", {q[1], {q[2], q[3]}}},
    (* SubValues (f[x_][y_] := ...) are not implemented *)
    {"q[x_][y_] := x + y; q[1][2]", 3}
